import {componentDefinitions,componentDefaults,validComponentProperties} from './scene-components.js';
// Live movement may edit a TRS array in place. Keep the channel sample and
// preanimated baseline private so physics cannot mutate a hidden layer.
export function sequenceTransformChannel(object,property,vm,hooks){const clone=value=>Array.isArray(value)?value.slice():value;return {mix:property==='visible'?undefined:property==='rotation'?'rotation':'linear',read:()=>clone(object[property]),apply:value=>{object[property]=clone(value);hooks.update(object);},valid:()=>vm.object(object.id)===object};}
export function sequenceComponent(object,track){const c=object?.components?.find(c=>c.id===track.component),field=c&&componentDefinitions[c.type]?.properties[track.property];if(!field||c.type!==track.componentType||!['number','checkbox','vec3','color','text','select','asset','sortinglayer'].includes(field.type))throw Error('시퀀스 컴포넌트 속성이 없어요: '+track.property);return {component:c,field,value:structuredClone(c.properties?.[track.property]??componentDefaults(c.type)[track.property])};}
export function validSequenceComponent(track,value){try{const type=track.componentType,field=componentDefinitions[type]?.properties[track.property];return typeof track.component==='string'&&track.component.length>0&&track.component.length<=100&&!!field&&['number','checkbox','vec3','color','text','select','asset','sortinglayer'].includes(field.type)&&validComponentProperties(type,{...componentDefaults(type),[track.property]:value});}catch{return false;}}
export function recordableComponents(object){const rows=[];for(const c of object.components||[]){if(c.type==='Transform'||!componentDefinitions[c.type])continue;const defaults=componentDefaults(c.type),properties={...defaults,...c.properties};if(!validComponentProperties(c.type,properties))throw Error('녹화 컴포넌트 값을 확인하세요: '+c.name);for(const [property,field] of Object.entries(componentDefinitions[c.type].properties)){if(!['number','checkbox','vec3','color','text','select','asset','sortinglayer'].includes(field.type))continue;rows.push({component:c.id,componentType:c.type,property,value:structuredClone(properties[property]),default:structuredClone(defaults[property]),discrete:!['vec3','color'].includes(field.type)&&(field.type!=='number'||field.step===1)});}}return rows;}
